{
  "schemaVersion": "0.2",
  "slug": "timeline",
  "name": "Timeline",
  "family": "D",
  "status": "experimental",
  "purpose": "Presents a chronologically ordered list of events with markers and timestamps.",
  "scenarios": [
    "Show order fulfillment steps",
    "Display activity history",
    "Present project milestones"
  ],
  "props": {
    "items": {
      "type": "string",
      "required": true,
      "description": "Array of { id, title, description?, time? } events in order."
    },
    "emptyLabel": {
      "type": "string",
      "required": false,
      "description": "Text shown when items is empty."
    },
    "className": {
      "type": "string",
      "required": false,
      "description": "Additional CSS classes."
    }
  },
  "variants": [],
  "states": [
    {
      "name": "default",
      "description": "Timeline with events."
    },
    {
      "name": "empty",
      "description": "No events to show."
    }
  ],
  "composition": {
    "allowedParents": [
      "card",
      "page",
      "app-shell"
    ],
    "allowedChildren": [
      "text",
      "badge"
    ],
    "requiredContext": []
  },
  "antiPatterns": [
    "Do not render events out of chronological order.",
    "Do not use a timeline for navigation between pages."
  ],
  "a11y": {
    "role": "list",
    "keyboard": [],
    "focus": "Items are not focusable unless they contain actions.",
    "labeling": "Ordered list semantics convey chronology; timestamps use time elements.",
    "wcag": [
      "1.3.1"
    ]
  },
  "responsive": {
    "strategy": "Vertical rail at all breakpoints; indentation follows inline direction.",
    "breakpoints": {
      "compact": "Narrow rail.",
      "medium": "Default rail.",
      "large": "Default rail."
    }
  },
  "platforms": {
    "web": "supported",
    "react": "supported",
    "vue": "planned"
  },
  "rtl": {
    "supported": true,
    "strategy": "Logical CSS only. Direction inherits from document lang/dir.",
    "mirroredValues": []
  },
  "dataAi": {
    "role": "timeline",
    "states": [
      "default",
      "empty"
    ],
    "intents": [
      "enumerate-items"
    ]
  }
}

.cu-timeline {
  display: block;
  color: var(--cu-color-fg-default);
}

.cu-timeline__list {
  list-style: none;
  margin: 0;
  padding: 0;
}

.cu-timeline__item {
  display: flex;
  gap: var(--cu-space-2);
  padding-block-end: var(--cu-space-3);
  position: relative;
}

.cu-timeline__marker {
  flex: none;
  inline-size: var(--cu-space-2);
  block-size: var(--cu-space-2);
  margin-block-start: var(--cu-space-1);
  border-radius: 50%;
  background: var(--cu-color-palette-brand);
}

.cu-timeline__title {
  font-weight: 600;
}

.cu-timeline__time {
  margin-inline-start: var(--cu-space-2);
  color: color-mix(in srgb, var(--cu-color-fg-default) 72%, transparent);
  font-size: 0.875em;
}

.cu-timeline__description {
  margin: var(--cu-space-1) 0 0;
}

.cu-timeline__empty {
  color: color-mix(in srgb, var(--cu-color-fg-default) 72%, transparent);
}

import './styles.css'

export interface TimelineItem {
  id: string
  title: string
  description?: string
  time?: string
}

export interface TimelineProps {
  items: TimelineItem[]
  emptyLabel?: string
  className?: string
}

export function Timeline({ items, emptyLabel = 'No events yet', className }: TimelineProps) {
  const classes = ['cu-timeline', className].filter(Boolean).join(' ')
  return (
    <div className={classes} data-ai-role="timeline" data-ai-intent="enumerate-items" data-ai-state={items.length === 0 ? 'empty' : 'default'}>
      {items.length === 0 ? (
        <p className="cu-timeline__empty">{emptyLabel}</p>
      ) : (
        <ol className="cu-timeline__list">
          {items.map((item) => (
            <li key={item.id} className="cu-timeline__item">
              <span className="cu-timeline__marker" aria-hidden="true" />
              <div className="cu-timeline__content">
                <span className="cu-timeline__title">{item.title}</span>
                {item.time ? <time className="cu-timeline__time">{item.time}</time> : null}
                {item.description ? <p className="cu-timeline__description">{item.description}</p> : null}
              </div>
            </li>
          ))}
        </ol>
      )}
    </div>
  )
}
